#!/usr/bin/env python3
"""Build /root/safety_audit_brief_final.hwpx from template + JSON data.

This script:
- Reads /root/audit_overview.json and /root/corrective_actions.json
- Extracts /root/safety_audit_template.hwpx
- Replaces {{placeholders}} in all XML files (robust to split runs by working per-paragraph)
- Normalizes inspection date YYYY-MM-DD -> YYYY.MM.DD everywhere
- Appends severity note to risk tier everywhere it appears
- Removes layout cache (<hp:lineSegArray> / <hp:linesegarray>) for modified paragraphs
- Verifies no {{...}} placeholders remain
- Repackages into /root/safety_audit_brief_final.hwpx
"""

from __future__ import annotations

import json
import os
import re
import shutil
import sys
import tempfile
import zipfile
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Tuple
import xml.etree.ElementTree as ET


ROOT_DIR = Path("/root")
TEMPLATE_PATH = ROOT_DIR / "safety_audit_template.hwpx"
OVERVIEW_JSON = ROOT_DIR / "audit_overview.json"
ACTIONS_JSON = ROOT_DIR / "corrective_actions.json"
OUTPUT_PATH = ROOT_DIR / "safety_audit_brief_final.hwpx"

HP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"


def localname(tag: str) -> str:
    # Tag may be '{uri}name' or plain 'name'
    if tag.startswith("{"):
        return tag.rsplit("}", 1)[1]
    return tag


def read_json(path: Path) -> dict:
    with path.open("r", encoding="utf-8") as f:
        return json.load(f)


def format_date_yyyy_mm_dd_to_dots(s: str) -> str:
    # Replace any YYYY-MM-DD occurrences with YYYY.MM.DD
    return re.sub(r"(\d{4})-(\d{2})-(\d{2})", r"\1.\2.\3", s)


def risk_with_severity(raw: str) -> str:
    mapping = {
        "High": "즉시조치",
        "Medium": "계획보완",
        "Low": "모니터링",
    }
    note = mapping.get(raw)
    if not note:
        return raw
    return f"{raw} {note}"


def build_replacements(overview: dict, actions: dict) -> Tuple[Dict[str, str], str, str]:
    summary = overview.get("summary") or {}

    inspection_date_raw = str(summary.get("점검일", ""))
    inspection_date_dot = format_date_yyyy_mm_dd_to_dots(inspection_date_raw)

    risk_raw = str(summary.get("위험등급", ""))
    risk_full = risk_with_severity(risk_raw)

    replacements: Dict[str, str] = {}

    for k, v in summary.items():
        key = str(k)
        val = "" if v is None else str(v)
        if key == "점검일":
            val = inspection_date_dot
        elif key == "위험등급":
            val = risk_full
        replacements[f"{{{{{key}}}}}"] = val

    immediate = actions.get("immediate_actions") or []
    if not isinstance(immediate, list):
        raise ValueError("corrective_actions.json: immediate_actions must be a list")

    # Fill first three lines in order. If fewer provided, fill missing with empty.
    for i in range(3):
        val = ""
        if i < len(immediate):
            val = "" if immediate[i] is None else str(immediate[i])
        replacements[f"{{{{조치{i+1}}}}}"] = val

    return replacements, inspection_date_raw, risk_raw


def discover_namespaces(xml_path: Path) -> Dict[str, str]:
    ns: Dict[str, str] = {}
    # iterparse with 'start-ns' yields (prefix, uri)
    for event, item in ET.iterparse(str(xml_path), events=("start-ns",)):
        prefix, uri = item
        # Keep first occurrence of each prefix
        if prefix not in ns:
            ns[prefix] = uri
    return ns


def register_namespaces(ns: Dict[str, str]) -> None:
    for prefix, uri in ns.items():
        # ElementTree reserves '' for default namespace.
        ET.register_namespace(prefix, uri)


def iter_paragraphs(root: ET.Element) -> Iterable[ET.Element]:
    for el in root.iter():
        if localname(el.tag) == "p":
            yield el


def iter_text_nodes(paragraph: ET.Element) -> List[ET.Element]:
    t_nodes: List[ET.Element] = []
    for el in paragraph.iter():
        if localname(el.tag) == "t":
            t_nodes.append(el)
    return t_nodes


def remove_layout_cache(paragraph: ET.Element, parent_map: Dict[ET.Element, ET.Element]) -> int:
    removed = 0
    # Remove both <hp:lineSegArray> and <hp:linesegarray> variants if present.
    for el in list(paragraph.iter()):
        ln = localname(el.tag)
        if ln in ("lineSegArray", "linesegarray"):
            parent = parent_map.get(el)
            if parent is not None:
                parent.remove(el)
                removed += 1
    return removed


def apply_replacements_to_xml(xml_path: Path, replacements: Dict[str, str], inspection_date_raw: str, risk_raw: str) -> None:
    ns = discover_namespaces(xml_path)
    register_namespaces(ns)

    tree = ET.parse(str(xml_path))
    root = tree.getroot()

    # Parent pointers needed to remove layout cache elements
    parent_map: Dict[ET.Element, ET.Element] = {c: p for p in root.iter() for c in p}

    modified_paragraphs = 0
    removed_caches = 0

    risk_full = risk_with_severity(risk_raw) if risk_raw else ""

    # A regex that replaces the raw risk tier only when it isn't already suffixed.
    # We do this post-placeholder replacement to catch both placeholder and literal occurrences.
    risk_re: Optional[re.Pattern[str]] = None
    if risk_raw and risk_full and risk_raw != risk_full:
        # Match as a standalone token (not embedded in an identifier) and not already followed by known suffix.
        # Example matches: 'High', 'High,' 'High)'
        suffixes = "즉시조치|계획보완|모니터링"
        risk_re = re.compile(
            rf"(?<![A-Za-z0-9_]){re.escape(risk_raw)}(?![A-Za-z0-9_])(?!(?:\\s*(?:{suffixes})))"
        )

    for p in iter_paragraphs(root):
        t_nodes = iter_text_nodes(p)
        if not t_nodes:
            continue

        original_text = "".join((t.text or "") for t in t_nodes)
        if not original_text:
            continue

        new_text = original_text

        # Replace placeholders
        for placeholder, value in replacements.items():
            if placeholder in new_text:
                new_text = new_text.replace(placeholder, value)

        # Normalize dates everywhere (including within replaced fields)
        new_text = format_date_yyyy_mm_dd_to_dots(new_text)

        # Ensure risk tier includes severity note everywhere
        if risk_re is not None:
            new_text = risk_re.sub(risk_full, new_text)

        if new_text != original_text:
            # Consolidate paragraph text into the first <hp:t>, clear others.
            t_nodes[0].text = new_text
            for extra in t_nodes[1:]:
                extra.text = ""

            modified_paragraphs += 1
            removed_caches += remove_layout_cache(p, parent_map)

    tree.write(str(xml_path), encoding="utf-8", xml_declaration=True)


def find_remaining_placeholders_in_text(xml_text: str) -> List[str]:
    # Non-greedy in case multiple placeholders are present
    return re.findall(r"\{\{.*?\}\}", xml_text)


def rebuild_zip(extracted_dir: Path, out_path: Path) -> None:
    if out_path.exists():
        out_path.unlink()

    all_files = [p for p in extracted_dir.rglob("*") if p.is_file()]

    # Keep stable ordering for deterministic output
    def rel(p: Path) -> str:
        return str(p.relative_to(extracted_dir)).replace(os.sep, "/")

    all_files_sorted = sorted(all_files, key=lambda p: rel(p))

    mimetype = extracted_dir / "mimetype"

    with zipfile.ZipFile(out_path, "w") as z:
        if mimetype.exists():
            z.write(mimetype, arcname="mimetype", compress_type=zipfile.ZIP_STORED)

        for p in all_files_sorted:
            arc = rel(p)
            if arc == "mimetype":
                continue
            z.write(p, arcname=arc, compress_type=zipfile.ZIP_DEFLATED)


def main() -> int:
    if not TEMPLATE_PATH.exists():
        print(f"Template not found: {TEMPLATE_PATH}", file=sys.stderr)
        return 2

    overview = read_json(OVERVIEW_JSON)
    actions = read_json(ACTIONS_JSON)

    replacements, inspection_date_raw, risk_raw = build_replacements(overview, actions)

    with tempfile.TemporaryDirectory(prefix="hwpx_build_") as td:
        td_path = Path(td)
        extracted_dir = td_path / "extracted"
        extracted_dir.mkdir(parents=True, exist_ok=True)

        with zipfile.ZipFile(TEMPLATE_PATH, "r") as z:
            z.extractall(extracted_dir)

        xml_files = [p for p in extracted_dir.rglob("*.xml") if p.is_file()]
        if not xml_files:
            print("No XML files found in template.", file=sys.stderr)
            return 3

        for xml_path in xml_files:
            apply_replacements_to_xml(xml_path, replacements, inspection_date_raw, risk_raw)

        # Verify: no placeholders remain in any XML
        remaining: List[Tuple[str, List[str]]] = []
        for xml_path in xml_files:
            text = xml_path.read_text(encoding="utf-8")
            matches = find_remaining_placeholders_in_text(text)
            if matches:
                remaining.append((str(xml_path.relative_to(extracted_dir)), matches))

        if remaining:
            print("ERROR: Remaining placeholders detected; aborting.", file=sys.stderr)
            for name, matches in remaining:
                # Deduplicate but keep stable ordering
                uniq = []
                for m in matches:
                    if m not in uniq:
                        uniq.append(m)
                print(f"- {name}: {uniq}", file=sys.stderr)
            return 4

        rebuild_zip(extracted_dir, OUTPUT_PATH)

    print(f"Wrote: {OUTPUT_PATH}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

